const CHITRAKOTE_COORDS=[19.2065,81.7],HEIGHT_COMPARISONS=[{name:"Chitrakote Falls (height)",heightMeters:29,note:"~29m (95 ft) drop — modest height, but exceptional width"},{name:"Chitrakote Falls (monsoon width)",heightMeters:300,note:"Up to ~300m (980 ft) wide in monsoon — India's widest waterfall"},{name:"Niagara Falls, Horseshoe (width)",heightMeters:670,note:"For comparison: Horseshoe Falls at Niagara is roughly 670m wide"},{name:"Jog Falls (height)",heightMeters:253,note:"India's highest un-tiered waterfall, for height comparison"}],SEASON_VIEWS=[{stage:"monsoon",title:"Monsoon → Waterfall View",img:"https://images.unsplash.com/photo-1620641622310-c1c243e4959c?auto=format&fit=crop&q=80&w=900",alt:"Chitrakote Falls in full monsoon flood, wide horseshoe of roaring reddish-brown water",text:"Between July and October the Indravati is at full volume, spreading nearly 300 metres across the escarpment in an unbroken, reddish-brown horseshoe curtain. The roar carries for kilometres and mist rises high enough to be seen well before the falls come into view."},{stage:"dry",title:"Lower Flow → Waterfall View",img:"https://images.unsplash.com/photo-1432405972618-c60b0225b8f9?auto=format&fit=crop&q=80&w=900",alt:"Chitrakote Falls in the dry season, narrower clear streams over exposed rock",text:"Through winter and summer the river contracts to as few as three separate streams over the same curved rock lip, running clear rather than silt-red. Lower water lets boats approach the base of the falls, something impossible during peak monsoon."}],GALLERY_IMAGES=[{url:"https://images.unsplash.com/photo-1620641622310-c1c243e4959c?auto=format&fit=crop&q=80&w=800",caption:"Panoramic view of Chitrakote Falls' full horseshoe width during monsoon",category:"Panoramic Hero"},{url:"https://images.unsplash.com/photo-1432405972618-c60b0225b8f9?auto=format&fit=crop&q=80&w=800",caption:"Chitrakote Falls with reduced, clearer flow in the dry season",category:"Dry-Season View"},{url:"https://images.unsplash.com/photo-1508739773434-c26b3d09e071?auto=format&fit=crop&q=80&w=800",caption:"The Indravati River winding through dense Bastar sal forest above the falls",category:"River & Landscape"},{url:"https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&q=80&w=800",caption:"Forested plateau landscape surrounding the Bastar region",category:"Surrounding Landscape"}],NEARBY_ATTRACTIONS=[{name:"Tirathgarh Falls",distance:"35 km",lat:18.9569,lng:81.8514,description:"A multi-tiered waterfall on the Kanger River inside Kanger Valley National Park."},{name:"Kanger Valley National Park",distance:"40 km",lat:18.921,lng:81.937,description:"Protected forest known for limestone caves, the Kanger river, and rich biodiversity."},{name:"Kailash & Kotamsar Caves",distance:"45 km",lat:18.95,lng:81.933,description:"Limestone cave systems with stalactite and stalagmite formations inside Kanger Valley."},{name:"Bastar Palace & Anthropological Museum",distance:"38 km",lat:19.0819,lng:82.0281,description:"Former royal residence and museum on Bastar's tribal art, culture and history, in Jagdalpur."}],REFERENCES=[{text:"Wikipedia — Chitrakote Falls, Bastar District, Chhattisgarh.",link:"https://en.wikipedia.org/wiki/Chitrakote_Falls"},{text:"Chhattisgarh Tourism Board — Chitrakote.",link:"https://tourism.cgstate.gov.in/destinations/Bastar/Chitrakote"},{text:"Incredible India (Government of India) — Chitrakote Waterfalls, Jagdalpur.",link:"https://www.incredibleindia.gov.in/en/chhattisgarh/jagdalpur/chitrakote-waterfalls"},{text:"Images: Unsplash contributors (used under the Unsplash License for demonstration purposes).",link:"https://unsplash.com/license"}];"undefined"!=typeof module&&module.exports&&(module.exports={CHITRAKOTE_COORDS:CHITRAKOTE_COORDS,HEIGHT_COMPARISONS:HEIGHT_COMPARISONS,SEASON_VIEWS:SEASON_VIEWS,GALLERY_IMAGES:GALLERY_IMAGES,NEARBY_ATTRACTIONS:NEARBY_ATTRACTIONS,REFERENCES:REFERENCES});